<template>
 <main class="context-page">
  <nav aria-label="位置"><router-link to="/agents">Agent 管理</router-link> / 上下文绑定</nav>
  <header><h1>模型节点上下文绑定</h1><p>为真实 Agent 候选逐个绑定角色、提示词与上下文工具，并由独立审核人作出决定。</p></header>
  <session-panel/>
  <p class="boundary">本页只登记和审核固定绑定。绑定获批后仍需真实专业执行链；当前部署不支持绑定后的运行准备。</p>
  <p v-if="prerequisite" class="prerequisite" role="status">{{ prerequisite }}</p>
  <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="loading" role="status">正在核查当前记录…</p>
  <section v-if="user.medicalSession?.current_context" class="card">
   <h2>项目范围</h2><div class="actions"><button type="button" :disabled="busy" @click="loadProjects(false)">读取可见项目</button><button v-if="projectCursor" type="button" :disabled="busy" @click="loadProjects(true)">更多项目</button><button type="button" :disabled="busy" @click="refreshAvailability">重新核查服务</button></div>
   <label>当前项目<select v-model="project" :disabled="busy"><option value="">请选择项目</option><option v-for="p in projects" :key="p.project_id" :value="p.project_id">{{ p.name }}</option></select></label>
  </section>
  <section v-if="pending" class="card recovery" aria-label="原请求只读恢复"><h2>上次操作需要核查</h2><p>{{ pending.kind === 'AUTHOR' ? '绑定登记' : '审核决定' }}的完整原请求已保存。只读核查不会重发、换键或再次提交决定。</p><p v-if="pending.receipt">已收到原操作回执；仍需核验固定内容和审核链。</p><button type="button" :disabled="busy || !availability?.features.context_bindings" @click="recover">只读核查原操作</button><details><summary>查看原请求核对信息</summary><dl><dt>原请求键</dt><dd>{{ pending.key }}</dd><dt>项目</dt><dd>{{ pending.project_id }}</dd><dt>原请求摘要</dt><dd>{{ pending.body_sha256 }}</dd><dt>操作理由</dt><dd>{{ pending.body.reason }}</dd><template v-if="pending.receipt"><dt>原操作标识</dt><dd>{{ pending.receipt.operation_id }}</dd><dt>原操作状态</dt><dd>{{ statusLabel(pending.receipt.status) }} · 修订 {{ pending.receipt.revision }}</dd></template></dl></details></section>
  <section class="card"><h2>绑定目录</h2><div class="actions"><button type="button" :disabled="busy || !canRead" @click="list(false)">读取项目绑定</button><button v-if="cursor" type="button" :disabled="busy || !canRead" @click="list(true)">读取下一页</button></div><p v-if="listed && !items.length">当前项目未返回可见的上下文绑定。</p><ul class="directory"><li v-for="item in items" :key="item.binding.version_id"><div><strong>{{ statusLabel(item.status) }}</strong><span>创建于 {{ item.created_at }} · 修订 {{ item.revision }}</span></div><button type="button" :disabled="busy" @click="open(item)">查看固定详情</button></li></ul></section>
  <section v-if="detail" class="card"><formal-evaluation-context-detail :view="detail"/><button type="button" :disabled="busy || !canRead" @click="refreshDetail">重新读取当前状态</button></section>
  <section class="card"><h2>候选与策略核查</h2><p>先读取候选目录，再选择并核查完整固定声明。审核已有绑定时，须选择该绑定引用的候选。</p><fieldset :disabled="busy || !canRead"><label>候选归属范围<select v-model="candidateScope"><option value="PROJECT">当前项目</option><option value="ENTERPRISE">当前企业</option></select></label><div class="actions"><button type="button" @click="loadCandidates(false)">读取 Agent 候选</button><button v-if="candidateCursor" type="button" @click="loadCandidates(true)">更多候选</button></div><label>Agent 候选<select v-model="candidateId"><option value="">请选择真实候选</option><option v-for="item in candidates" :key="item.record_id" :value="item.record_id">{{ item.name || '未命名候选' }} · {{ item.created_at }} · {{ item.status === 'DISABLED' ? '已停用' : '固定候选' }}</option></select></label><button type="button" :disabled="!candidateId" @click="loadCandidate">核查所选候选与固定策略</button></fieldset>
   <template v-if="candidate && policy"><p><strong>{{ candidate.name }}</strong> · 执行策略{{ policy.status === 'APPROVED' ? '已批准' : '尚未批准' }} · {{ nodes.length }} 个模型节点</p><details><summary>查看候选与策略核对信息</summary><dl><dt>候选作者</dt><dd>{{ candidate.created_by }}</dd><dt>候选固定版本</dt><dd>{{ candidate.basis.version_id }}</dd><dt>候选摘要</dt><dd>{{ candidate.basis.content_sha256 }}</dd><dt>策略固定版本</dt><dd>{{ candidate.execution_policy.version_id }}</dd><dt>策略摘要</dt><dd>{{ candidate.execution_policy.content_sha256 }}</dd></dl></details></template>
  </section>
  <form v-if="candidate && policy && !pending" class="card" @submit.prevent="submitAuthor"><h2>编写节点绑定</h2><p>角色沿用所选策略中的固定角色；请为每个模型节点明确选择提示词与上下文工具。不会推测缺失的依赖或资格。</p><fieldset :disabled="busy || !mayAuthor || !canRead"><label>工具目录归属范围<select v-model="toolScope"><option value="PROJECT">当前项目</option><option value="ENTERPRISE">当前企业</option></select></label><div class="actions"><button type="button" @click="loadTools(false)">读取候选内工具</button><button v-if="toolCursor" type="button" @click="loadTools(true)">更多工具</button></div>
   <section v-for="node in nodes" :key="node.node_kind" class="node"><h3>{{ node.node_kind }} · 模型节点</h3><p>固定角色：{{ shortId(node.role.version_id) }}（来自所选执行策略）</p><label>提示词<select v-model="node.prompt_id"><option value="">明确选择提示词</option><option v-for="(prompt,index) in candidate.manifest.prompt_revisions" :key="prompt.version_id" :value="prompt.version_id">候选提示词 {{ index+1 }} · {{ shortId(prompt.version_id) }}</option></select></label><label>上下文工具<select v-model="node.tool_id"><option value="">明确选择已读取工具</option><option v-for="tool in tools" :key="tool.record_id" :value="tool.version_id">上下文工具 · {{ tool.created_at }} · {{ shortId(tool.version_id) }}</option></select></label><button type="button" :disabled="!node.tool_id" @click="readTool(node.tool_id)">核查工具固定声明</button><p v-if="loadedTool(node.tool_id)">工具固定声明已核查；输入和输出契约取自真实工具及候选清单。</p><details v-if="loadedTool(node.tool_id)"><summary>查看工具契约与来源</summary><dl><dt>输入契约</dt><dd>{{ loadedTool(node.tool_id)?.input_schema.schema_ref }}</dd><dt>输出契约</dt><dd>{{ loadedTool(node.tool_id)?.output_schema.schema_ref }}</dd><dt>来源制品</dt><dd>{{ loadedTool(node.tool_id)?.source_artifact.version_id }}</dd></dl></details></section>
   <label>登记理由<textarea v-model="authorReason" maxlength="2000" rows="3"/></label><label class="attestation"><input v-model="authorAttested" type="checkbox"/>已逐项核查全部模型节点，确认仅登记待审核绑定</label></fieldset><button type="submit" :disabled="busy || !canRead || !mayAuthor || !authorAttested || !nodes.length">保存待审核绑定</button></form>
  <form v-if="detail && !pending && ['DRAFT','APPROVED'].includes(detail.status)" class="card" @submit.prevent="submitDecision"><h2>独立审核决定</h2><p>本次决定绑定上方固定内容及修订 {{ detail.revision }}。绑定作者和候选作者均不能审核；状态改变后不会自动重试。</p><fieldset :disabled="busy || !canRead"><label>决定<select v-model="decision"><option value="">请选择本次决定</option><option v-if="detail.status==='DRAFT'" value="APPROVE">批准固定绑定</option><option v-if="detail.status==='DRAFT'" value="REJECT">拒绝固定绑定</option><option v-if="detail.status==='APPROVED'" value="DISABLE">停用已批准绑定</option></select></label><label>审核理由<textarea v-model="decisionReason" maxlength="2000" rows="3"/></label><p v-if="reviewIssue" role="status">{{ reviewIssue }}</p><label class="attestation"><input v-model="decisionAttested" type="checkbox"/>已核查固定内容、候选作者和当前修订，确认提交所选决定</label></fieldset><button type="submit" :disabled="busy || !canRead || !!reviewIssue || !decisionAttested">提交独立审核决定</button></form>
 </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import useUserStore from '@/store/modules/user'
import SessionPanel from './session-panel.vue'
import FormalEvaluationContextDetail from './formal-evaluation-context-detail.vue'
import { contextAvailability, contextAllowed, contextDecisionIssue, contextInputIssue, queryContexts, readContext, readPendingContext, submitContext, recoverContext, detached } from '@/api/medical/formal-evaluation-context'
import type { ContextAvailability, ContextView, ContextSummary, ContextStatus, ContextDecisionKind, ContextDecide, PendingContext } from '@/api/medical/formal-evaluation-context'
import { buildContextAuthor, loadContextCandidate, loadContextTool, modelNodeSelections, sameBasis } from '@/api/medical/formal-evaluation-context-form'
import type { ContextCandidate, ContextTool, NodeSelection } from '@/api/medical/formal-evaluation-context-form'
import { capabilityProjectCandidates } from '@/api/medical/formal-capability-candidates'
import { queryDrafts } from '@/api/medical/formal-agent-drafts'
import type { DraftSummary } from '@/api/medical/formal-agent-drafts'
import type { PolicyView } from '@/api/medical/execution-policy-domain'
import type { MedicalSession, Project } from '@/api/medical/protocol'
const user = useUserStore(), project = ref(''), projects = ref<Project[]>([]), projectCursor = ref<string|null>(null), availability = ref<ContextAvailability|null>(null)
const items = ref<ContextSummary[]>([]), cursor = ref<string|null>(null), listed = ref(false), detail = ref<ContextView|null>(null), pending = ref<PendingContext|null>(null)
const candidates = ref<DraftSummary[]>([]), candidateCursor = ref<string|null>(null), candidateId = ref(''), candidateScope = ref('PROJECT'), candidate = ref<ContextCandidate|null>(null), policy = ref<PolicyView|null>(null)
const tools = ref<DraftSummary[]>([]), toolCursor = ref<string|null>(null), toolScope = ref('PROJECT'), checkedTools = ref<ContextTool[]>([]), nodes = ref<NodeSelection[]>([])
const authorReason = ref(''), authorAttested = ref(false), decision = ref<ContextDecisionKind|''>(''), decisionReason = ref(''), decisionAttested = ref(false), loading = ref(false), error = ref(''), notice = ref('')
let controller = new AbortController(), generation = 0, mounted = true, writeOwner: object|null = null
const busy = computed(()=>loading.value || user.medicalWriting), canRead = computed(()=>!!user.medicalSession?.current_context && !!project.value && availability.value?.features.context_bindings===true)
const mayAuthor = computed(()=>contextAllowed(user.medicalSession,project.value,'AUTHOR'))
const prerequisite = computed(()=>!user.medicalSession?.current_context ? '请先恢复身份并选择企业，再读取项目范围。' : availability.value === null ? '请先核查当前部署的上下文绑定服务。' : !availability.value.features.context_bindings ? availability.value.unavailable_reason === 'DEPENDENCY_UNAVAILABLE' ? '当前部署缺少上下文绑定所需依赖，暂不可读取或提交绑定。' : '当前部署尚未启用上下文绑定服务。' : !project.value ? '请选择一个真实项目，读取该项目的绑定与候选。' : !mayAuthor.value ? '当前项目没有绑定登记权限；仍可按已有读取与审核权限核查记录。' : '')
const reviewCandidateAuthor = computed(()=>detail.value && candidate.value && sameBasis(detail.value.fixed.definition.candidate,candidate.value.basis) ? candidate.value.created_by : null)
const reviewIssue = computed(()=>!decision.value ? '请明确选择本次审核决定。' : contextDecisionIssue(user.medicalSession,detail.value,reviewCandidateAuthor.value,decision.value))
const statusLabel = (status: ContextStatus)=>({DRAFT:'待审核',APPROVED:'已批准',REJECTED:'已拒绝',DISABLED:'已停用'})[status]
const shortId = (id:string)=>id.slice(0,8)+'…'+id.slice(-6)
const loadedTool = (id:string)=>checkedTools.value.find(x=>x.basis.version_id===id)
function reader(): MedicalSession { if (!user.medicalSession?.current_context) throw new Error('请先恢复身份并选择企业'); return user.medicalSession }
function live(g:number,s:MedicalSession) { return mounted && generation===g && user.medicalSession===s && !document.hidden }
async function run(work:(signal:AbortSignal,current:()=>boolean)=>Promise<void>,write=false) {
 if (busy.value || !user.medicalSession?.current_context || document.hidden) return
 const s=reader(),g=generation,signal=controller.signal,owner={}; loading.value=true;error.value='';notice.value=''
 if (write) { writeOwner=owner; user.medicalWriting=true }
 try { await work(signal,()=>live(g,s)) } catch (failure) { if (live(g,s) && !signal.aborted) error.value=failure && typeof failure==='object' && 'message' in failure && typeof failure.message==='string'?failure.message:'请求未完成，请核查原操作' }
 finally { if (live(g,s)) loading.value=false; if (writeOwner===owner) { writeOwner=null;user.medicalWriting=false;if (mounted&&generation!==g&&user.medicalSession?.current_context&&!document.hidden) void bootstrap() } }
}
function invalidate() { controller.abort();controller=new AbortController();generation++;loading.value=false;error.value='';notice.value='' }
function clearCandidate() { candidate.value=null;policy.value=null;nodes.value=[];tools.value=[];toolCursor.value=null;checkedTools.value=[];authorReason.value='';authorAttested.value=false;decisionReason.value='';decisionAttested.value=false;decision.value='' }
function clearProject() { invalidate();items.value=[];cursor.value=null;listed.value=false;detail.value=null;candidates.value=[];candidateCursor.value=null;candidateId.value='';clearCandidate() }
function clear() { clearProject();project.value='';projects.value=[];projectCursor.value=null;availability.value=null;pending.value=null;candidateScope.value='PROJECT';toolScope.value='PROJECT' }
async function bootstrap() { if (!user.medicalSession?.current_context || document.hidden) return; try { pending.value=readPendingContext(reader()) } catch (failure) { error.value=failure && typeof failure==='object' && 'message' in failure && typeof failure.message==='string'?failure.message:'原请求记录无法核查'; return } return run(async(signal,current)=>{const a=await contextAvailability(reader,signal);if(current())availability.value=a}) }
async function refreshAvailability() { return bootstrap() }
async function loadProjects(more:boolean) { return run(async(signal,current)=>{const page=await capabilityProjectCandidates(reader,more?projectCursor.value:null,signal);if(current()){projects.value=more?[...projects.value,...page.projects]:page.projects;projectCursor.value=page.next_after}}) }
async function list(more:boolean) { if(!canRead.value)return;return run(async(signal,current)=>{const page=await queryContexts(reader,project.value,more?cursor.value:null,signal);if(current()){items.value=page.items;cursor.value=page.next_cursor;listed.value=true;detail.value=null;decision.value='';decisionReason.value=''}}) }
function installDetail(view:ContextView) { detail.value=view;decision.value='';decisionReason.value='';decisionAttested.value=false }
async function open(item:ContextSummary) { if(!canRead.value)return;return run(async(signal,current)=>{const view=await readContext(reader,item.binding.version_id,signal);if(view.fixed.definition.project_id!==project.value||!sameBasis(view.binding,item.binding))throw new Error('目录与固定绑定项目或身份不一致，请重新读取');if(current())installDetail(view)}) }
async function refreshDetail() { if(!detail.value||!canRead.value)return;const id=detail.value.binding.version_id;return run(async(signal,current)=>{const view=await readContext(reader,id,signal);if(current())installDetail(view)}) }
async function loadCandidates(more:boolean) { if(!canRead.value)return;return run(async(signal,current)=>{const page=await queryDrafts(reader,'AGENT',candidateScope.value==='PROJECT'?project.value:null,more?candidateCursor.value:null,signal);if(current()){candidates.value=more?[...candidates.value,...page.items]:page.items;candidateCursor.value=page.next_cursor}}) }
async function loadCandidate() { const summary=candidates.value.find(x=>x.record_id===candidateId.value);if(!summary||!canRead.value)return;return run(async(signal,current)=>{const result=await loadContextCandidate(reader,summary,project.value,signal);if(current()){clearCandidate();candidate.value=result.candidate;policy.value=result.policy;try{nodes.value=modelNodeSelections(result.candidate,result.policy)}catch(failure){error.value=failure && typeof failure==='object' && 'message' in failure && typeof failure.message==='string'?failure.message:'候选缺少模型节点'}}}) }
async function loadTools(more:boolean) { if(!canRead.value||!candidate.value)return;const selected=candidate.value;return run(async(signal,current)=>{const page=await queryDrafts(reader,'TOOL',toolScope.value==='PROJECT'?project.value:null,more?toolCursor.value:null,signal);if(current()){const matching=page.items.filter(x=>selected.manifest.tool_versions.some(b=>b.version_id===x.version_id&&b.content_sha256===x.content_sha256));tools.value=[...tools.value,...matching].filter((x,index,all)=>all.findIndex(y=>y.record_id===x.record_id)===index);toolCursor.value=page.next_cursor;if(!matching.length)notice.value='本页没有候选清单内的工具；可继续读取目录或切换归属范围。'}}) }
async function readTool(id:string) { const summary=tools.value.find(x=>x.version_id===id),selected=candidate.value;if(!summary||!selected||!canRead.value)return;return run(async(signal,current)=>{const value=await loadContextTool(reader,summary,selected,project.value,signal);if(current())checkedTools.value=[...checkedTools.value.filter(x=>x.basis.version_id!==id),value]}) }
function body() { return buildContextAuthor(project.value,candidate.value,policy.value,nodes.value,checkedTools.value,authorReason.value) }
async function submitAuthor() { if(busy.value||!canRead.value||!mayAuthor.value||pending.value||!authorAttested.value)return;let request;try{request=body();const issue=contextInputIssue('AUTHOR',request);if(issue)throw new Error(issue)}catch(failure){error.value=failure && typeof failure==='object' && 'message' in failure && typeof failure.message==='string'?failure.message:'请检查节点绑定';return}return run(async(signal,current)=>{await submitContext(reader,'AUTHOR',request,project.value,signal,p=>{if(current())pending.value=p});if(current()){authorAttested.value=false;notice.value='已收到绑定登记回执。请只读核查原操作，确认完整固定内容。'}},true) }
async function submitDecision() { const target=detail.value;if(!target||!decision.value||busy.value||pending.value||!canRead.value||!decisionAttested.value||reviewIssue.value)return;const request:ContextDecide={schema_version:'1.0.0',binding:detached(target.binding),expected_revision:target.revision,decision:decision.value,reason:decisionReason.value};const issue=contextInputIssue('DECISION',request);if(issue){error.value=issue;return}return run(async(signal,current)=>{await submitContext(reader,'DECISION',request,target.fixed.definition.project_id,signal,p=>{if(current())pending.value=p});if(current()){decisionAttested.value=false;notice.value='已收到独立审核回执。请只读核查原操作和决定链。'}},true) }
async function recover() { const original=pending.value;if(!original||availability.value?.features.context_bindings!==true)return;return run(async(signal,current)=>{const view=await recoverContext(reader,detached(original),signal);if(current()){pending.value=null;if(project.value===view.fixed.definition.project_id)installDetail(view);notice.value='原键、完整原请求与固定审核链已核验。当前状态为'+statusLabel(view.status)+'。'}}) }
watch(()=>user.medicalSession,()=>{clear();if(user.medicalSession?.current_context&&!document.hidden)void bootstrap()},{deep:true,immediate:true,flush:'sync'})
watch(project,()=>clearProject(),{flush:'sync'})
watch(candidateScope,()=>{invalidate();candidates.value=[];candidateCursor.value=null;candidateId.value='';clearCandidate()},{flush:'sync'})
watch(candidateId,()=>{invalidate();clearCandidate()},{flush:'sync'})
watch(toolScope,()=>{invalidate();toolCursor.value=null},{flush:'sync'})
watch(()=>user.medicalWriting,(writing)=>{if(!writing && !availability.value && user.medicalSession?.current_context && !document.hidden)void bootstrap()},{flush:'sync'})
watch([nodes,authorReason,candidate,policy,checkedTools],()=>{authorAttested.value=false},{deep:true,flush:'sync'})
watch([decision,decisionReason,detail,candidate],()=>{decisionAttested.value=false},{deep:true,flush:'sync'})
function visibility(){clear();if(!document.hidden&&user.medicalSession?.current_context)void bootstrap()}
function unload(e:BeforeUnloadEvent){if(writeOwner||!pending.value&&(authorReason.value||decisionReason.value)){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(()=>!user.medicalWriting)
document.addEventListener('visibilitychange',visibility);window.addEventListener('beforeunload',unload)
onBeforeUnmount(()=>{mounted=false;invalidate();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('beforeunload',unload)})
</script>
<style scoped>
.context-page{max-width:1160px;margin:auto;padding:1.5rem;display:grid;gap:1.1rem}h1{font-size:1.75rem;margin:.3rem 0}h2{font-size:1.2rem;margin:0 0 .7rem}h3{font-size:1rem}.card{padding:1.3rem;border:1px solid var(--el-border-color);border-radius:10px;background:var(--el-fill-color-blank)}p{line-height:1.6;margin:.5rem 0}.boundary{color:var(--el-text-color-secondary)}.prerequisite,.recovery{background:var(--el-color-warning-light-9);border-left:3px solid var(--el-color-warning);padding:1rem}.actions{display:flex;gap:.7rem;flex-wrap:wrap}label{display:grid;gap:.45rem;margin:1rem 0}input,select,textarea{font:inherit;padding:.6rem;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-fill-color-blank);color:var(--el-text-color-primary);max-width:100%}button{font:inherit;padding:.55rem .9rem;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-fill-color-blank);color:var(--el-text-color-primary);cursor:pointer}button[type=submit]{background:var(--el-color-primary);color:white}button:disabled{opacity:.5;cursor:not-allowed}fieldset{border:0;padding:0;min-width:0}.attestation{display:flex;align-items:start}.node{padding:1rem;margin:1rem 0;border:1px solid var(--el-border-color);border-radius:8px}.directory{padding:0;list-style:none}.directory li{display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:.8rem 0;border-bottom:1px solid var(--el-border-color)}.directory span{display:block;color:var(--el-text-color-secondary);font-size:.9rem}details{margin:.8rem 0}summary{cursor:pointer;color:var(--el-color-primary)}dt{font-weight:600}dd{margin:.3rem 0 .8rem;overflow-wrap:anywhere}.error{color:var(--el-color-danger)}@media(max-width:680px){.context-page{padding:.8rem}.card{padding:1rem}.directory li{align-items:start;flex-direction:column}}
</style>
